[IO.File]::WriteAllText((Join-Path $PWD 'expire.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Sets a key that lives two seconds, reads it, waits three seconds, and reads it again.`n# Usage: sh expire.sh <port>`nr=redis://127.0.0.1:`$1`ncurl -s -u alice:s3cret `"`$r/SET/session/abc/PX/2000`" `"`$r/GET/session`" `"`$r/PTTL/session`" | {`n  read -r set; read -r value; read -r ttl`n  echo `"set: `$set`"`n  echo `"before: `$value`"`n  [ `"`$ttl`" -gt 0 ] && echo `"time to live: positive`"`n}`nsleep 3`ncurl -s -u alice:s3cret `"`$r/GET/session`" `"`$r/PTTL/session`" `"`$r/EXISTS/session`" | {`n  read -r value; read -r ttl; read -r exists`n  echo `"after: [`$value]`"`n  echo `"time to live: `$ttl`"`n  echo `"exists: `$exists`"`n}`n")
$server0 = Start-Process surl -ArgumentList '--user', 'alice:s3cret', '--allow-plaintext-auth', 'redis://127.0.0.1:8080' -PassThru -NoNewWindow
